mapper.select:
select *
from ai_chat_message
where session_id = #{sessionId}
  and student_id = #{studentId}
order by id asc

select *
from (
    select *
    from ai_chat_message
    where session_id = #{sessionId}
      and student_id = #{studentId}
      and role in ('user', 'assistant')
      and compressed = 0
    order by id desc
    limit #{limit}
) recent
order by id asc
